import base64
import zlib
from pathlib import Path

PAYLOAD = """"""

out = Path(__file__).resolve().parents[1] / "site" / "assets" / "runes-hd.svg"
out.parent.mkdir(parents=True, exist_ok=True)
out.write_text(zlib.decompress(base64.b64decode(PAYLOAD)).decode("utf-8"), encoding="utf-8")
print(f"Wrote {out}")
